    public static Path2D parse(String d) {
        Path2D path = new Path2D.Double();

        // 명령어 기준으로 분리
        // 예: "M233.67,403.92L235.15,406.59L237.54,406.84Z"
        String[] tokens = d.split("(?=[MLZ])"); // M, L, Z 앞에서 분리

        for (String token : tokens) {
            token = token.trim();
            if (token.isEmpty()) continue;

            char cmd = token.charAt(0);
            String coords = token.substring(1).trim();

            switch (cmd) {
                case 'M': {
                    String[] xy = coords.split(",");
                    double x = Double.parseDouble(xy[0]);
                    double y = Double.parseDouble(xy[1]);
                    path.moveTo(x, y);
                    break;
                }
                case 'L': {
                    String[] xy = coords.split(",");
                    double x = Double.parseDouble(xy[0]);
                    double y = Double.parseDouble(xy[1]);
                    path.lineTo(x, y);
                    break;
                }
                case 'Z': {
                    path.closePath();
                    break;
                }
            }
        }

        return path;
    }
	
